import string

def validate_password(password: str) -> list:
    issues = []
    if len(password) < 12:
        issues.append("too_short")
    if not any(c.isupper() for c in password):
        issues.append("no_upper")
    if not any(c.islower() for c in password):
        issues.append("no_lower")
    if not any(c.isdigit() for c in password):
        issues.append("no_digit")
    if not any(c in string.punctuation for c in password):
        issues.append("no_symbol")
    if any(c.isspace() for c in password):
        issues.append("has_space")
    common_passwords = {"password", "123456", "qwerty", "letmein", "admin", "welcome"}
    if password.lower() in common_passwords or "password" in password.lower():
        issues.append("common")
    return issues

