The code has two issues:
1. **Cyclomatic complexity** of `validate_password` is 9 (exceeds 5). This is caused by complex lambdas.  
2. **Lint errors**: Trailing whitespace on two blank lines.

**Fix**:  
- Split each lambda into a separate helper function.  
- Remove trailing whitespace.  

Fixed code:  
```python
import string

COMMON_PASSWORDS = {"password", "123456", "qwerty", "letmein", "admin", "welcome"}

def _is_too_short(p):
    return len(p) < 12

def _no_upper(p):
    return not any(c.isupper() for c in p)

def _no_lower(p):
    return not any(c.islower() for c in p)

def _no_digit(p):
    return not any(c.isdigit() for c in p)

def _no_symbol(p):
    return not any(c in string.punctuation for c in p)

def _has_space(p):
    return any(c.isspace() for c in p)

def _is_common(p):
    p_lower = p.lower()
    return (p_lower in COMMON_PASSWORDS) or ("password" in p_lower)

def validate_password(password: str) -> list:
    rules = [
        ("too_short", _is_too_short),
        ("no_upper", _no_upper),
        ("no_lower", _no_lower),
        ("no_digit", _no_digit),
        ("no_symbol", _no_symbol),
        ("has_space", _has_space),
        ("common", _is_common),
    ]

    issues = []
    for name, condition in rules:
        if condition(password):
            issues.append(name)

    return issues
